import asyncio
from typing import Optional, Dict, Any
from mcp import ClientSession, types, MCPError, UNSUPPORTED_PROTOCOL_VERSION
from pydantic import ValidationError

def discover_server_capabilities(read_stream: Optional[Any] = None, write_stream: Optional[Any] = None) -> Dict[str, Any]:
    """Probe the server for its capabilities and supported versions. read_stream: Read stream for session messages, write_stream: Write stream for session messages.

    Example:
    >>> discover_server_capabilities()
    {'capabilities': {...}, 'supported_versions': ['2024-11-01']}
    """
    async def _run_discover():
        session = ClientSession(read_stream=read_stream, write_stream=write_stream)
        try:
            result = await session.discover()
            return {
                "capabilities": result.capabilities.model_dump() if result.capabilities else None,
                "supported_versions": list(result.supported_versions) if result.supported_versions else []
            }
        finally:
            if hasattr(session, 'close'):
                await session.close()

    try:
        return asyncio.run(_run_discover())
    except ValueError:
        raise
    except Exception as e:
        if isinstance(e, MCPError):
            raise ValueError(f"MCP error during discovery: {str(e)}") from e
        raise ValueError(f"Unexpected error during discovery: {str(e)}") from e
