from mcp import ClientSession
from mcp.types import ReadResourceResult, InputRequiredResult


def read_resource_content(uri: str) -> Dict[str, Any]:
    """Read the content of a specific resource from the server. uri: The URI of the resource to read, e.g. 'file:///example.txt' -> {'content': 'file contents here'}."""

    async def _read_resource_async():
        # Create a minimal client session for this operation
        session = ClientSession()

        try:
            result = await session.read_resource(uri=uri)

            if isinstance(result, InputRequiredResult):
                raise RuntimeError("Input required but not allowed")

            if isinstance(result, ReadResourceResult):
                return {"content": result.content}
            else:
                raise RuntimeError(f"Unexpected result type: {type(result)}")

        except Exception as e:
            raise RuntimeError(f"Failed to read resource: {str(e)}")

    # Run the async function synchronously
    try:
        return asyncio.run(_read_resource_async())
    except Exception as e:
        raise ValueError(f"Invalid URI or read error: {str(e)}")
