def list_tools() -> list[dict[str, str | list[str] | None]]:
    """List all registered tools. Returns a list of tool dictionaries with name, description, and parameters."""
    try:
        from mcp.server.mcpserver.server import ToolManager
        manager = ToolManager()
        tools = manager.list_tools()
        result = []
        for tool in tools:
            tool_dict = {
                "name": tool.name,
                "description": tool.description,
                "parameters": []
            }
            if hasattr(tool, 'parameters'):
                for param in tool.parameters:
                    param_dict = {
                        "name": param.name,
                        "type": str(param.type),
                        "required": param.required
                    }
                    if hasattr(param, 'description'):
                        param_dict["description"] = param.description
                    tool_dict["parameters"].append(param_dict)
            result.append(tool_dict)
        return result
    except Exception as e:
        raise ValueError(f"Failed to list tools: {str(e)}")
