def execute_tool_across_servers(
    tool_name: str, 
    arguments: Optional[Dict[str, Any]] = None
) -> List[Union[Dict[str, Any], str]]:
    """Execute a tool across multiple connected MCP servers. tool_name: name of the tool to execute, arguments: optional arguments to pass to the tool. Returns list of results from each server."""

    if not isinstance(tool_name, str):
        raise ValueError("tool_name must be a string")

    if arguments is not None and not isinstance(arguments, dict):
        raise ValueError("arguments must be a dictionary or None")

    async def _run():
        exit_stack = AsyncExitStack()
        try:
            session_group = mcp.ClientSessionGroup(exit_stack)

            # Get all available tools
            tools = list(session_group.tools.keys())
            if tool_name not in tools:
                raise ValueError(f"Tool '{tool_name}' not found among available tools: {tools}")

            # Execute tool on all sessions
            results = []
            for session_name, session in session_group._sessions.items():
                try:
                    result = await session.call_tool(
                        session_group.tools[tool_name].name,
                        arguments=arguments,
                        allow_input_required=False
                    )
                    results.append({
                        "server": session_name,
                        "result": str(result)
                    })
                except Exception as e:
                    results.append({
                        "server": session_name,
                        "error": str(e)
                    })

            return results

        finally:
            await exit_stack.aclose()

    try:
        return asyncio.run(_run())
    except Exception as e:
        raise RuntimeError(f"Failed to execute tool across servers: {str(e)}")
