from typing import Dict, Any, Optional, Union
from pydantic import ValidationError
from mcp.shared.jsonrpc_dispatcher import MCPError, ErrorData, INVALID_PARAMS


def handler_exception_to_error_data(exc: BaseException) -> Optional[Dict[str, Any]]:
    """Map a handler-raised exception to its wire `ErrorData`. exc: A BaseException instance to be converted, e.g. MCPError -> ErrorData, ValidationError -> INVALID_PARAMS error."""
    if isinstance(exc, MCPError):
        return exc.error.dict() if hasattr(exc.error, 'dict') else dict(exc.error)
    if isinstance(exc, ValidationError):
        return {"code": INVALID_PARAMS, "message": "Invalid request parameters", "data": ""}
    return None
